sparql:
SELECT ?name ?tactic ?category ?riskLevel ?owner WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name .
    OPTIONAL { ?m proto:tactic ?tactic }
    OPTIONAL { ?m proto:category ?cat . ?cat skos:prefLabel ?category }
    OPTIONAL { ?m proto:riskLevel ?rl . ?rl skos:prefLabel ?riskLevel }
    OPTIONAL { ?m proto:owner ?ow . ?ow skos:prefLabel ?owner }
} ORDER BY ?name

SELECT ?name ?description ?tactic ?riskLevel WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name ;
       proto:tactic "Credential Access" .
    OPTIONAL { ?m proto:description ?description }
    OPTIONAL { ?m proto:riskLevel ?rl . ?rl skos:prefLabel ?riskLevel }
} ORDER BY ?name

SELECT ?name ?mitreId ?description WHERE {
    ?t a proto:TTP ;
       proto:name ?name .
    OPTIONAL { ?t proto:mitreId ?mitreId }
    OPTIONAL { ?t proto:description ?description }
} ORDER BY ?name

SELECT ?tacticLabel (COUNT(?m) AS ?moduleCount) WHERE {
    ?tactic a skos:Concept ;
            skos:inScheme ?scheme ;
            skos:prefLabel ?tacticLabel .
    FILTER(CONTAINS(STR(?scheme), "mitre-tactics"))
    OPTIONAL {
        ?m a proto:LibraryModule ;
           proto:tactic ?tacticLabel .
    }
} GROUP BY ?tacticLabel ORDER BY ?moduleCount

SELECT ?teamName (COUNT(?m) AS ?moduleCount) WHERE {
    ?team a proto:Team ;
          proto:name ?teamName .
    OPTIONAL {
        ?m a proto:LibraryModule .
        ?m proto:owner ?team .
    }
} GROUP BY ?teamName ORDER BY DESC(?moduleCount)

SELECT ?name ?tactic ?riskLevel WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name .
    ?m proto:riskLevel ?rl .
    ?rl skos:prefLabel ?riskLevel .
    FILTER(?riskLevel = "High" || ?riskLevel = "Critical")
    OPTIONAL { ?m proto:tactic ?tactic }
} ORDER BY ?name

SELECT ?fromName ?toName WHERE {
    ?from rel:LEADS_TO ?to .
    ?from proto:name ?fromName .
    ?to proto:name ?toName .
} ORDER BY ?fromName

SELECT ?name ?tactic WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name .
    OPTIONAL { ?m proto:tactic ?tactic }
} ORDER BY ?name LIMIT 25

SELECT ?name WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name .
} ORDER BY ?name LIMIT 25

SELECT ?name ?tactic WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name ;
       proto:tactic ?t .
    FILTER(CONTAINS(STR(?t), "TA0006"))
} ORDER BY ?name LIMIT 25

SELECT ?name ?tactic WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name ;
       proto:tactic ?t .
    FILTER(CONTAINS(STR(?t), "TA0008"))
} ORDER BY ?name LIMIT 25

SELECT ?tacticLabel (COUNT(DISTINCT ?m) AS ?count) WHERE {
    ?m a proto:LibraryModule ;
       proto:tactic ?t .
    ?t skos:prefLabel ?tacticLabel .
} GROUP BY ?tacticLabel ORDER BY DESC(?count) LIMIT 25

SELECT DISTINCT ?tacticLabel WHERE {
    ?t skos:prefLabel ?tacticLabel .
    FILTER(CONTAINS(STR(?t), "mitre-TA"))
    FILTER(NOT EXISTS { ?m a proto:LibraryModule ; proto:tactic ?t . })
} ORDER BY ?tacticLabel

SELECT ?concept ?label WHERE {
    ?c a ?concept .
    OPTIONAL { ?c skos:prefLabel ?label }
} LIMIT 25

SELECT ?tactic ?tacticLabel WHERE {
    ?m a proto:LibraryModule ;
       proto:tactic ?t .
    OPTIONAL { ?t skos:prefLabel ?tacticLabel }
} LIMIT 25

SELECT ?tacticLabel (COUNT(?m) AS ?count) WHERE {
    ?m a proto:LibraryModule ; proto:tactic ?t .
    OPTIONAL { ?t skos:prefLabel ?tacticLabel }
} GROUP BY ?tacticLabel ORDER BY DESC(?count) LIMIT 25

SELECT ?name ?tactic WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name .
    OPTIONAL { ?m proto:tactic ?t . ?t skos:prefLabel ?tactic }
} ORDER BY ?name LIMIT 25

SELECT ?techniqueLabel ?cve WHERE {
    ?m a proto:LibraryModule ;
       proto:tactic ?t .
    ?t skos:prefLabel ?techniqueLabel .
    OPTIONAL { ?m proto:hasCVE ?cve }
} ORDER BY ?techniqueLabel LIMIT 25

SELECT ?name ?cve WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name ;
       proto:tactic ?t .
    FILTER(CONTAINS(STR(?t), "TA0006"))
    OPTIONAL { ?m proto:hasCVE ?cve }
} ORDER BY ?name LIMIT 25

SELECT ?name ?tacticLabel WHERE {
    ?m a proto:LibraryModule ;
       proto:name ?name ;
       proto:tactic ?t .
    ?t skos:prefLabel ?tacticLabel .
    FILTER(CONTAINS(STR(?t), "TA0001"))
